package com.openggf.game.soniccd;
import com.openggf.game.save.SaveManager;
import com.openggf.game.session.SessionManager;
import com.openggf.game.soniccd.level.*;
import com.openggf.game.soniccd.objects.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.parallel.Isolated;
import java.util.*;
import java.util.concurrent.atomic.*;
import static org.junit.jupiter.api.Assertions.*;
/** Strict genuine arrival obligation, never a catch-as-success or constructed B context. All Java UNRUN. */
@Isolated class TestCdOriginalPastEnemyWorld extends TestCdOriginalR11LoadingWorld {
 @Test void genuinePastFirstMainReturnsAfterAntonPataAndTheConnectedEnemyFamily()throws Exception{
  var source=TestCdOriginalBootPrefix.source();var attempt=SonicCdGameModule.prepareSelectedProfile(source,new SaveManager(root),1,SonicCdGameModule.ProfileEntry.NEW_GAME,0);var m=attempt.module().orElseThrow();try(var boot=boot()){var loop=boot.bootSonicCdSelectedProfile(source,attempt);readyPast(loop,m);var frame=m.originalR11EntryFrame();var registry=SessionManager.getCurrentGameplayMode().getRewindRegistry();var full=registry.capture();var course=registry.captureCourse();step(loop,0);assertFalse(frame.closed());assertEquals(1,frame.environment().globals().levelFrames());var slots=m.originalR11PlacementImage().pool().slots();assertEquals(0x3F,slots.get(0).id());assertEquals(0x3E,slots.get(1).id());assertEquals(2,slots.get(1).routine());assertEquals((slots.get(1).subtype()==0?CdR11bObjectData.Table.MAP_SPR_PATA_BATA1:CdR11bObjectData.Table.MAP_SPR_PATA_BATA2).nativeAddress(),slots.get(1).longBits(CdObjectState.LongField.MAPPINGS));assertEquals(0x2A,slots.get(1).unsignedByte(CdObjectState.ByteField.COLLISION_TYPE));var expected=image(m);registry.restore(full);step(loop,0);CdCapturedValueAssertions.assertCapturedValueEquals(expected,image(m));registry.restoreCourse(course);step(loop,0);CdCapturedValueAssertions.assertCapturedValueEquals(expected,image(m));}
 }
 @Test void idleBorrowedConnectedBodiesCannotMutateTheCurrentPastWorld()throws Exception{
  var source=TestCdOriginalBootPrefix.source();var attempt=SonicCdGameModule.prepareSelectedProfile(source,new SaveManager(root),1,SonicCdGameModule.ProfileEntry.NEW_GAME,0);var m=attempt.module().orElseThrow();try(var boot=boot()){var loop=boot.bootSonicCdSelectedProfile(source,attempt);readyPast(loop,m);var before=image(m);var wf=SonicCdGameModule.class.getDeclaredField("r11World");wf.setAccessible(true);var bf=CdWorld.class.getDeclaredField("binding");bf.setAccessible(true);var binding=bf.get(wf.get(m));for(String name:new String[]{"enemyPataBata","mosqui","enemyTamabboh"}){var field=binding.getClass().getDeclaredField(name);field.setAccessible(true);var body=field.get(binding);assertNotNull(body);if(body instanceof CdPataBata pata)assertThrows(IllegalStateException.class,()->pata.run(33,new CdPataBata.Globals(0,0,0,0)));else if(body instanceof CdMosqui mosqui){var actual=m.originalR11PlacementImage().pool().slots().stream().filter(slot->slot.id()==CdMosqui.OBJECT_ID).findFirst();if(actual.isPresent())assertThrows(IllegalStateException.class,()->mosqui.run(actual.orElseThrow().identity().wholeIndex(),new CdMosqui.Globals(0,0,0,0,0,0,0)));else assertThrows(IllegalArgumentException.class,()->mosqui.run(32,new CdMosqui.Globals(0,0,0,0,0,0,0)));}else{var tam=assertInstanceOf(CdTamabboh.class,body);assertThrows(IllegalStateException.class,()->tam.run(32,new CdTamabboh.Globals(0,0,0,0,0,0)));}CdCapturedValueAssertions.assertCapturedValueEquals(before,image(m));}assertFalse(m.originalR11EntryFrame().closed());}
 }
 @Test void foreignThreadServiceRejectsBeforePastEnemyMainMutation()throws Exception{
  var source=TestCdOriginalBootPrefix.source();var attempt=SonicCdGameModule.prepareSelectedProfile(source,new SaveManager(root),1,SonicCdGameModule.ProfileEntry.NEW_GAME,0);var m=attempt.module().orElseThrow();try(var boot=boot()){var loop=boot.bootSonicCdSelectedProfile(source,attempt);readyPast(loop,m);var before=image(m);var error=new AtomicReference<Throwable>();var thread=new Thread(()->{try{step(loop,0);}catch(Throwable failure){error.set(failure);}},"foreign-Past-enemy-service");thread.start();thread.join();assertInstanceOf(IllegalStateException.class,error.get());CdCapturedValueAssertions.assertCapturedValueEquals(before,image(m));assertFalse(m.originalR11EntryFrame().closed());}
 }
 private static void readyPast(com.openggf.GameLoop loop,SonicCdGameModule m){
  for(int n=0;n<256&&m.originalR11LoadingPrefix().main().levelStartedByte()!=1;n++)step(loop,0);assertEquals(SonicCdR31aLoadingVisit.Phase.READY,m.originalR11LoadingImage().phase());for(int n=0;n<6351;n++)step(loop,((n>=4000&&n<4032)||(n>=4096&&n<4128)||(n>=4608&&n<4640)||(n>=6000&&n<6032))?0x18:8);
  for(int n=0;n<22;n++)step(loop,8);step(loop,0);step(loop,0);for(int n=0;n<90;n++)step(loop,0);step(loop,0);for(int n=0;n<24;n++)step(loop,0);step(loop,0x80);for(int n=0;n<24;n++)step(loop,0);step(loop,0);step(loop,0);assertEquals(CdCommand.R11B,m.originalWarpDestination().orElseThrow().command());step(loop,0);
  for(int n=0;n<256&&m.originalR11LoadingImage().phase()!=SonicCdR31aLoadingVisit.Phase.READY;n++)step(loop,0);assertEquals(SonicCdR31aLoadingVisit.Phase.READY,m.originalR11LoadingImage().phase());assertEquals(CdStagePayload.R11B.stage(),m.originalR11EntryFrame().stageSource().stage());assertEquals(0,m.originalR11EntryFrame().environment().movement().gates().timeZone());
 }
 private static Object image(SonicCdGameModule m){var f=m.originalR11EntryFrame();var p=m.originalR11PlacementImage();return List.of(f.captureActor(),f.captureShared(),p.status(),p.pool().slots(),p.savedFlags(),m.originalR11LoadingImage(),m.originalR11LoadingPrefix(),m.originalR11WorldImage(),m.originalR11TimeWarpSavedImage(),m.programServicesState(),m.programSoundRequests());}
}
